solutions.javascript:
const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const adj = Array.from({ length: n + 1 }, () => []);
const indeg = new Array(n + 1).fill(0);
for (let i = 0; i < m; i++) {
  const a = tok[2 + 2 * i], b = tok[3 + 2 * i];
  adj[a].push(b);
  indeg[b]++;
}
const h = [];
const push = (x) => {
  h.push(x);
  let i = h.length - 1;
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (h[p] <= h[i]) break;
    [h[p], h[i]] = [h[i], h[p]];
    i = p;
  }
};
const pop = () => {
  const top = h[0], last = h.pop();
  if (h.length) {
    h[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let s = i;
      if (l < h.length && h[l] < h[s]) s = l;
      if (r < h.length && h[r] < h[s]) s = r;
      if (s === i) break;
      [h[s], h[i]] = [h[i], h[s]];
      i = s;
    }
  }
  return top;
};
for (let v = 1; v <= n; v++) if (indeg[v] === 0) push(v);
const order = [];
while (h.length) {
  const u = pop();
  order.push(u);
  for (const v of adj[u]) if (--indeg[v] === 0) push(v);
}
console.log(order.length === n ? order.join(" ") : "IMPOSSIBLE");

